function admin_pagination(int $pageNum,int $pages,string $base): void {
 echo '<nav class="pagination" aria-label="Pagination"><span>Page '.$pageNum.' of '.$pages.'</span><div>';
 if($pageNum>1) echo '<a class="button secondary compact" href="'.e($base.'page='.($pageNum-1)).'">← Previous</a>';
 if($pageNum<$pages) echo '<a class="button secondary compact" href="'.e($base.'page='.($pageNum+1)).'">Next →</a>';
 echo '</div></nav>';
}
